<script lang="ts">import type {LoadFocusBar} from '../generated/LoadFocusBar';import {colors,clamp} from '../charts';let {bars}:{bars:LoadFocusBar[]}=$props();let max=$derived(Math.max(900,...bars.map(b=>b.target?.[1]??b.value)));</script>{#each bars as b,i}<div class="lf"><div class="top"><span>{b.name} {#if b.shortage}<em>Shortage</em>{/if}</span><b>{Math.round(b.value)}</b></div><div class="bar">{#if b.target}<u style:left={clamp(b.target[0]/max)*100+'%'} style:width={(clamp(b.target[1]/max)-clamp(b.target[0]/max))*100+'%'}></u>{/if}<i style:width={clamp(b.value/max)*100+'%'} style:background={[colors.sky,colors.flame,colors.violet][i%3]}></i></div></div>{/each}<style>.lf{margin-top:14px}.lf:first-child{margin-top:0}.top{display:flex;justify-content:space-between;align-items:center;font-size:13px;color:var(--text2);margin-bottom:8px}.top b{font:600 15px Outfit;color:var(--text)}em{font:600 11px Inter;color:var(--amber);background:rgba(255,181,71,.15);padding:4px 8px;border-radius:20px;font-style:normal}.bar{position:relative;height:10px;border-radius:5px;background:rgba(255,255,255,.06)}u{position:absolute;top:-3px;bottom:-3px;border:1.5px dashed rgba(255,255,255,.28);border-radius:7px}i{position:absolute;left:0;top:0;bottom:0;border-radius:5px}</style>